# Validates .ps1 scripts generated by Nalu without running them.
#
# 1. Parses each file with PowerShell's official parser (the same one that runs the scripts).
# 2. Rejects constructs that only exist in PowerShell 7, because Windows ships with 5.1:
#    ternary (a ? b : c), ??, ??=, && / || between commands, ?. / ?[], ForEach-Object -Parallel and
#    Join-String.
# 3. Checks the encoding: the generator writes ASCII only, without a BOM (`irm … | iex` breaks with a BOM); a
#    file with anything outside ASCII (a `native` block with accented characters) needs the BOM, otherwise 5.1 reads it as ANSI.
#
# Usage: pwsh -NoProfile -File tests/ps_syntax.ps1 file1.ps1 [file2.ps1 …]
# Exits 0 if everything is fine; otherwise lists the problems (file:line:column) and exits 1.

$ErrorActionPreference = 'Stop'
$problemas = New-Object 'System.Collections.Generic.List[string]'

function Adicionar([string]$Arquivo, $Extent, [string]$Mensagem) {
    $problemas.Add(('{0}:{1}:{2}: {3}' -f $Arquivo, $Extent.StartLineNumber, $Extent.StartColumnNumber, $Mensagem))
}

foreach ($arquivo in $args) {
    $bytes = [System.IO.File]::ReadAllBytes($arquivo)
    $bom = $bytes.Length -ge 3 -and $bytes[0] -eq 0xEF -and $bytes[1] -eq 0xBB -and $bytes[2] -eq 0xBF
    $ascii = $true
    for ($k = $(if ($bom) { 3 } else { 0 }); $k -lt $bytes.Length; $k++) { if ($bytes[$k] -gt 127) { $ascii = $false; break } }
    if ($bom -eq $ascii) {
        $problemas.Add("${arquivo}: BOM $(if ($bom) { 'present' } else { 'absent' }) with $(if ($ascii) { 'ASCII' } else { 'non-ASCII' }) content")
    }

    $tokens = $null
    $erros = $null
    $ast = [System.Management.Automation.Language.Parser]::ParseFile($arquivo, [ref]$tokens, [ref]$erros)

    foreach ($e in $erros) {
        Adicionar $arquivo $e.Extent ("syntax error: " + $e.Message)
    }

    # Tree nodes that do not exist in 5.1.
    $exclusivos7 = $ast.FindAll({
        param($n)
        $tipo = $n.GetType().Name
        if ($tipo -eq 'TernaryExpressionAst' -or $tipo -eq 'PipelineChainAst') { return $true }
        if ($n -is [System.Management.Automation.Language.BinaryExpressionAst] -and [string]$n.Operator -eq 'QuestionQuestion') { return $true }
        if ($n -is [System.Management.Automation.Language.AssignmentStatementAst] -and [string]$n.Operator -eq 'QuestionQuestionEquals') { return $true }
        if ($n -is [System.Management.Automation.Language.MemberExpressionAst] -and $null -ne $n.PSObject.Properties['NullConditional'] -and $n.NullConditional) { return $true }
        if ($n -is [System.Management.Automation.Language.IndexExpressionAst] -and $null -ne $n.PSObject.Properties['NullConditional'] -and $n.NullConditional) { return $true }
        if ($n -is [System.Management.Automation.Language.CommandParameterAst] -and $n.ParameterName -eq 'Parallel') { return $true }
        if ($n -is [System.Management.Automation.Language.CommandAst] -and $n.GetCommandName() -eq 'Join-String') { return $true }
        return $false
    }, $true)

    foreach ($n in $exclusivos7) {
        Adicionar $arquivo $n.Extent ("only exists in PowerShell 7 (Windows ships with 5.1): " + $n.Extent.Text)
    }
}

if ($problemas.Count -gt 0) {
    foreach ($p in $problemas) { [Console]::Error.WriteLine($p) }
    exit 1
}
[Console]::Out.WriteLine("ok: $($args.Count) file(s) valid for PowerShell 5.1")
exit 0
